{
  "css": ".trip-header {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) 44px;
  align-items: center;
  height: 62px;
  width: 100%;
}

.trip-header button {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  margin: 0;
  padding: 0;
  background: transparent;
  border: none;
  cursor: pointer;
  color: inherit;
  font: inherit;
}

.trip-header button img {
  width: 24px;
  height: 24px;
  display: block;
  opacity: 1;
}

.trip-header h1 {
  grid-column: 2;
  margin: 0;
  font-size: 18px;
  line-height: 26px;
  font-weight: 700;
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.trip-header span[aria-hidden="true"] {
  grid-column: 3;
  display: block;
  width: 44px;
  height: 44px;
}

@media (max-width: 360px) {
  .trip-header h1 {
    white-space: normal;
    overflow: visible;
    text-overflow: clip;
  }
}"
}
